// Extract all emails from the single webhook payload
const input = $input.first().json;

// n8n Webhook may nest POST body under input.body or directly on input
const data = input.body || input;

// Get emails array from payload
const emailsArray = data.emails || [];

if (emailsArray.length === 0) {
  // Fallback: maybe it was sent as single email (old format)
  if (data.email) {
    emailsArray.push(data.email);
  } else {
    throw new Error('No emails found in webhook payload. Keys: ' + Object.keys(data).join(', '));
  }
}

// Build a single combined prompt for ALL emails - classify and extract in one LLM call
let emailDescriptions = '';
let emailMetadata = [];

for (let i = 0; i < emailsArray.length; i++) {
  const email = emailsArray[i];
  const attachments = (email.attachments || []).map(a => a.file_name + ' (' + (a.file_category || 'file') + ', ' + (a.file_size_formatted || 'unknown size') + ')').join(', ');

  emailDescriptions += `\n---\nEMAIL ${i + 1}:\nFrom: ${email.from_name} <${email.from_email}>\nTo: ${email.to_name} <${email.to_email}>\nSubject: ${email.subject}\nDate: ${email.received_at}\nBody:\n${email.body_plain}\nAttachments: ${attachments || 'None'}\n`;

  emailMetadata.push({
    email_index: email.email_index != null ? email.email_index : i,
    id: email.id,
    from_name: email.from_name,
    from_email: email.from_email,
    to_name: email.to_name,
    to_email: email.to_email,
    subject: email.subject,
    body_plain: email.body_plain,
    received_at: email.received_at,
    attachments: (email.attachments || []).map(a => ({
      file_name: a.file_name,
      file_category: a.file_category || 'other',
      file_extension: a.file_extension || ''
    }))
  });
}

const classificationPrompt = `You are an insurance email processing expert. You will analyze ${emailsArray.length} emails and for EACH email:

1. CLASSIFY the email into exactly one category:
   - "BOR" = Broker of Record change/appointment request
   - "Cancellation" = Policy cancellation request
   - "Quote" = New insurance quote request
   - "Endorsement" = Policy change/endorsement request
   - "Renewal" = Policy renewal
   - "Claim" = Insurance claim
   - "General Inquiry" = General question
   - "Other" = Does not fit above

   CLASSIFICATION RULES:
   - If subject or body mentions "Broker of Record" or "BOR" -> category is "BOR"
   - If subject or body mentions "Cancellation" or "cancel" -> category is "Cancellation"
   - If subject or body mentions "Quote" or "quote request" -> category is "Quote"
   - If attachment names contain "Broker of Record" -> supports "BOR"
   - If attachment names contain "Cancellation" or "Policyholder Information" -> supports "Cancellation"
   - If attachment names contain "Insurance Application" or "Quote" -> supports "Quote"

2. EXTRACT these details from the email subject, body, and attachment names:
   - policy_number: Look for patterns like "Policy #XXX", "Policy Number: XXX", "#AUTO-TX-XXXX" etc. Return the full policy number string or null.
   - customer_id: Any customer/client ID mentioned, or null.
   - quote_number: Any quote reference number, or null.
   - attachment_type: Describe what the attachments are (e.g. "BOR Letter", "Cancellation Form + Proof of Sale", "Vehicle Insurance Application").
   - insured_name: The person/entity being insured if mentioned, or null.
   - effective_date: Any effective date mentioned, or null.
   - vehicle_info: Any vehicle details (year, make, model) mentioned, or null.

Here are the ${emailsArray.length} emails to analyze:
${emailDescriptions}

Respond with ONLY a valid JSON array (no markdown, no code blocks, no explanation). Each element corresponds to one email in order:
[
  {
    "email_index": 0,
    "category": "<category>",
    "confidence": <0.0-1.0>,
    "policy_number": "<value or null>",
    "customer_id": "<value or null>",
    "quote_number": "<value or null>",
    "attachment_type": "<description>",
    "email_subject": "<subject>",
    "email_body_summary": "<2-3 sentence summary>",
    "insured_name": "<value or null>",
    "effective_date": "<value or null>",
    "vehicle_info": "<value or null>"
  }
]`;

return [{
  json: {
    emailMetadata,
    classificationPrompt,
    totalEmails: emailsArray.length
  }
}];

// Parse classification results and build response generation prompt
const input = $input.first().json;
const prepData = $('Prepare All Emails').first().json;
const emailMetadata = prepData.emailMetadata || [];

// Parse Azure OpenAI classification response
let classifications = [];
let rawContent = '';
try {
  const choices = input.choices || (input.body && input.body.choices) || [];
  rawContent = choices[0].message.content;
  let jsonStr = rawContent.trim();
  // Strip markdown code blocks if present
  if (jsonStr.startsWith('```')) {
    jsonStr = jsonStr.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '').trim();
  }
  classifications = JSON.parse(jsonStr);
  if (!Array.isArray(classifications)) classifications = [classifications];
} catch(e) {
  // If parse fails, create fallback for each email
  for (let i = 0; i < emailMetadata.length; i++) {
    classifications.push({
      email_index: i,
      category: 'Unknown',
      confidence: 0,
      policy_number: null,
      customer_id: null,
      quote_number: null,
      attachment_type: null,
      email_subject: emailMetadata[i].subject,
      email_body_summary: 'Classification parse error: ' + e.message + ' | Raw: ' + rawContent.substring(0, 200),
      insured_name: null,
      effective_date: null,
      vehicle_info: null
    });
  }
}

// Build ONE prompt to generate professional responses for ALL emails
let responseInstructions = '';
for (let i = 0; i < classifications.length; i++) {
  const c = classifications[i];
  const meta = emailMetadata[i] || {};
  const attNames = (meta.attachments || []).map(a => a.file_name).join(', ');

  responseInstructions += `\n---\nEMAIL ${i + 1} (Category: ${c.category}, Confidence: ${((c.confidence || 0) * 100).toFixed(0)}%):\nFrom: ${meta.from_name || 'Unknown'} <${meta.from_email || ''}>\nSubject: ${meta.subject || 'No subject'}\nSummary: ${c.email_body_summary || 'N/A'}\nAttachments: ${attNames || 'None'}\nExtracted Details:\n  - Policy Number: ${c.policy_number || 'Not found'}\n  - Customer ID: ${c.customer_id || 'Not found'}\n  - Quote Number: ${c.quote_number || 'Not found'}\n  - Attachment Type: ${c.attachment_type || 'Not found'}\n  - Insured Name: ${c.insured_name || 'Not found'}\n  - Effective Date: ${c.effective_date || 'Not found'}\n  - Vehicle Info: ${c.vehicle_info || 'N/A'}\n`;
}

const responsePrompt = `You are a professional insurance operations assistant at Wonderland Global Insurance. Generate a professional response email for EACH of the ${classifications.length} emails below.

For each email response:
1. Acknowledge receipt of the email and all attachments by name
2. State the identified category clearly
3. List ALL extracted details that were found (policy number, customer ID, etc.)
4. For any details marked "Not found", mention that clarification may be needed
5. Provide specific next steps based on the category:
   - BOR: Confirm broker change processing, mention timeline
   - Cancellation: Confirm cancellation request received, mention refund review
   - Quote: Confirm quote application received, mention underwriting review
6. Sign as: Wonderland Team, Email Processing Division, Emailprocessing@wonderlandglobal.com

Emails to respond to:
${responseInstructions}

Respond with ONLY a valid JSON array (no markdown, no code blocks). Each element has the response text for that email:
[
  {
    "email_index": 0,
    "response_body": "<full professional response text>"
  }
]`;

return [{
  json: {
    classifications,
    emailMetadata,
    responsePrompt
  }
}];

// Build the final webhook response with all results
const input = $input.first().json;
const prevData = $('Parse & Prepare Responses').first().json;
const classifications = prevData.classifications || [];
const emailMetadata = prevData.emailMetadata || [];

// Parse generated responses
let responses = [];
try {
  const choices = input.choices || (input.body && input.body.choices) || [];
  let content = choices[0].message.content.trim();
  if (content.startsWith('```')) {
    content = content.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '').trim();
  }
  responses = JSON.parse(content);
  if (!Array.isArray(responses)) responses = [responses];
} catch(e) {
  // Fallback: generate basic responses
  for (let i = 0; i < emailMetadata.length; i++) {
    responses.push({
      email_index: i,
      response_body: 'Thank you for your email regarding \"' + (emailMetadata[i].subject || '') + '\". We have received your request and attachments. Our team is reviewing the details and will respond with next steps shortly.\n\nBest Regards,\nWonderland Team\nEmail Processing Division\nEmailprocessing@wonderlandglobal.com'
    });
  }
}

// Combine everything into final results array
const results = [];
for (let i = 0; i < emailMetadata.length; i++) {
  const meta = emailMetadata[i];
  const classif = classifications[i] || {};
  const resp = responses.find(r => r.email_index === i) || responses[i] || {};

  results.push({
    email_index: meta.email_index != null ? meta.email_index : i,
    email_id: meta.id || null,
    email_subject: meta.subject || 'Unknown',
    classification: {
      category: classif.category || 'Unknown',
      confidence: classif.confidence || 0
    },
    extracted_details: {
      policy_number: classif.policy_number || null,
      customer_id: classif.customer_id || null,
      quote_number: classif.quote_number || null,
      attachment_type: classif.attachment_type || null,
      insured_name: classif.insured_name || null,
      effective_date: classif.effective_date || null,
      vehicle_info: classif.vehicle_info || null,
      email_subject: classif.email_subject || meta.subject || null,
      email_body_summary: classif.email_body_summary || null
    },
    response: {
      from_name: 'Wonderland Team',
      from_email: 'Emailprocessing@wonderlandglobal.com',
      to_name: meta.from_name || '',
      to_email: meta.from_email || '',
      subject: 'RE: ' + (meta.subject || ''),
      body: resp.response_body || 'Thank you for your email. We are processing your request.',
      sent_at: new Date().toISOString()
    },
    attachments_processed: (meta.attachments || []).map(a => a.file_name)
  });
}

return [{
  json: {
    success: true,
    total_processed: results.length,
    processed_at: new Date().toISOString(),
    results
  }
}];
